<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { ArrowDown, ArrowUp, Check, ChevronDown, Database, LockKeyhole, Radio, RefreshCw, Save, Signal, SlidersHorizontal } from '@lucide/vue'
import { api,type Settings,type Summary } from '../services/api'
import { useTraffic,networkTotal,trafficInteger,trafficVolume,trafficSpeed } from '../services/traffic'
import '../cellular-page.css'

type ProfileID='profile1'|'profile2'
type APNProfile={id:ProfileID;enabled:boolean;apn:string;auth:number;usernameConfigured:boolean;passwordConfigured:boolean}
type ConfiguredProfile={status:string;source:string;current:false;observedAt:string;apn:string;auth:number;usernameConfigured:boolean;passwordConfigured:boolean;profile2Known:boolean;profile2Absent:boolean}
type APNSettings={revision:number;profiles:APNProfile[];savedAt:string|null;appliedRevision:number|null;appliedAt:string|null;applyAvailable?:boolean;applyReason?:string;applyInProgress?:boolean;configuredProfile1?:ConfiguredProfile|null}
type Draft=APNProfile&{username:string;password:string;clearUsername:boolean;clearPassword:boolean}
type APNJob={id?:string;revision?:number;status?:'queued'|'running'|'succeeded'|'failed';verified:boolean;appliedRevision?:number;code?:string;result?:{dataLink?:{status:string;linuxEgressConfigured?:boolean};restored?:boolean;recoveryRequired?:boolean}}
const props=defineProps<{summary:Summary}>(),emit=defineEmits<{refresh:[]}>()
const apn=ref<APNSettings>(),drafts=ref<Draft[]>([]),selected=ref<ProfileID>('profile1'),loading=ref(true),saving=ref(false),applying=ref(false),error=ref(''),message=ref(''),savedSnapshot=ref(''),plan=ref<Settings>(),limitDraft=ref(''),planBusy=ref(false),planError=ref(''),planMessage=ref('')
let active=true,jobRequest:AbortController|undefined
const observation=computed(()=>props.summary.modem),modem=computed(()=>['available','stale'].includes(observation.value?.status)?observation.value?.data:undefined)
const currentObservation=computed(()=>props.summary.apnCurrent),current=computed(()=>currentObservation.value?.status==='available'&&currentObservation.value?.data?.current===true?currentObservation.value.data:undefined)
const configured=computed(()=>apn.value?.configuredProfile1?.status==='available'&&apn.value.configuredProfile1.current===false?apn.value.configuredProfile1:undefined)
const apnName=computed(()=>current.value?.apn?{label:'現在のAPN',value:current.value.apn,saved:false,description:''}:configured.value?.apn?{label:'設定APN',value:configured.value.apn,saved:true,description:'本体の保存プロファイル'}:{label:'APN',value:'未取得',saved:false,description:''})
const networkNames:Record<string,string>={'44010':'NTT docomo','44020':'SoftBank','44021':'SoftBank','44050':'KDDI','44051':'KDDI','44052':'KDDI','44053':'KDDI','44054':'KDDI','44011':'Rakuten Mobile','44003':'IIJ'}
const carrier=computed(()=>modem.value?.carrier||networkNames[modem.value?.plmn]||(modem.value?.plmn?`PLMN ${modem.value.plmn}`:'回線情報を確認中'))
const stale=computed(()=>observation.value?.status==='stale')
const registered=computed(()=>stale.value?'前回の観測':modem.value?.registered===true?'回線登録済み':modem.value?.registered===false?'回線未登録':'登録情報待ち')
function bandLabel(value:string){return 'Band '+value.replace(/^B(?=\d)/,'')}
const band=computed(()=>Array.isArray(modem.value?.bands)&&modem.value.bands.length?modem.value.bands.map(bandLabel).join(' / '):modem.value?.band?bandLabel(modem.value.band):'—')
function metric(value:unknown,unit:string){return typeof value==='number'&&Number.isFinite(value)?`${value.toLocaleString('ja-JP',{maximumFractionDigits:1})} ${unit}`:'—'}
function date(value:string|null|undefined){if(!value||!Number.isFinite(Date.parse(value)))return '—';return new Date(value).toLocaleString('ja-JP',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'})}
function state(value:unknown){return value===true?'接続済み':value===false?'未接続':'未取得'}
const editor=computed(()=>drafts.value.find(profile=>profile.id===selected.value))
function serializable(){return drafts.value.map(({id,enabled,apn,auth,username,password,clearUsername,clearPassword})=>({id,enabled,apn,auth,...(username?{username}:{}),...(password?{password}:{}),...(clearUsername?{clearUsername:true}:{}),...(clearPassword?{clearPassword:true}:{})}))}
const dirty=computed(()=>JSON.stringify(serializable())!==savedSnapshot.value)
const enabledCount=computed(()=>apn.value?.profiles.filter(profile=>profile.enabled).length||0)
const applyDisabled=computed(()=>!apn.value||!apn.value.applyAvailable||!!apn.value.applyInProgress||!apn.value.profiles.find(p=>p.id==='profile1')?.enabled||!!apn.value.profiles.find(p=>p.id==='profile2')?.enabled||enabledCount.value===0||dirty.value||saving.value||loading.value||applying.value)
function installSettings(value:APNSettings){
 if(!Number.isInteger(value.revision)||value.revision<0||!Array.isArray(value.profiles)||value.profiles.length!==2||!['profile1','profile2'].every(id=>value.profiles.filter(p=>p.id===id&&typeof p.enabled==='boolean'&&typeof p.apn==='string'&&Number.isInteger(p.auth)&&p.auth>=0&&p.auth<=3&&typeof p.usernameConfigured==='boolean'&&typeof p.passwordConfigured==='boolean').length===1))throw new Error('APN設定の応答を確認できません')
 if(value.configuredProfile1===undefined&&apn.value?.configuredProfile1)value={...value,configuredProfile1:apn.value.configuredProfile1}
 apn.value=value;drafts.value=value.profiles.map(profile=>({...profile,username:'',password:'',clearUsername:false,clearPassword:false}));savedSnapshot.value=JSON.stringify(serializable())
}
function explain(e:unknown){const value=e instanceof Error?e.message:String(e);if(value.includes('REVISION_CONFLICT'))return '別の操作でAPN設定が変わりました。保存内容を読み直してから編集してください。';if(value.includes('APN_CREDENTIAL_CHARACTERS_INVALID'))return 'ユーザー名・パスワードは49文字以内の英数字と . _ - @ : + % = で入力してください。先頭のハイフンは使えません。';if(value.includes('APN_NAME_INVALID'))return 'APNは49文字以内の英数字・ハイフン・ドットで入力してください。';if(value.includes('APN_NO_ENABLED_PROFILE'))return '接続に使用するプロファイルを1つ以上有効にしてください。';return value}
async function loadAPN(preserveError=false){if(saving.value||applying.value)return;loading.value=true;if(!preserveError)error.value='';try{const value=await api<APNSettings>('/network/cellular/apn');if(active)installSettings(value)}catch(e){if(active)error.value=explain(e)}finally{if(active)loading.value=false}}
async function saveAPN(){if(!apn.value||saving.value||applying.value||!dirty.value)return;saving.value=true;error.value='';message.value='';try{const value=await api<APNSettings>('/network/cellular/apn','PUT',{expectedRevision:apn.value.revision,profiles:serializable()});if(active){installSettings(value);message.value='接続設定を保存しました。回線への適用はまだ行っていません。'}}catch(e){if(active)error.value=explain(e)}finally{if(active)saving.value=false}}
function applyFailure(job:APNJob){
 if(job.result?.restored)return '接続を確認できなかったため、元のAPN設定へ戻しました。'
 if(job.result?.recoveryRequired)return '適用後の状態を確認できません。現在の回線状態を確認してください。'
 if(job.code==='REVISION_CONFLICT')return '保存設定が変更されました。最新の設定を読み直してください。'
 if(job.code==='APN_APPLY_PROFILE2_UNSUPPORTED'||job.code==='APN_PROFILE2_MUST_BE_DISABLED')return 'プロファイル1を有効、プロファイル2を無効にして適用してください。'
 return 'APNの反映を確認できませんでした。現在の回線状態と保存設定を確認してください。'
}
async function trackJob(value:APNJob,revision:number){
 const deadline=Date.now()+95000
 if(value.id){if(!/^[a-f0-9]{48}$/.test(value.id))throw new Error('適用処理の応答を確認できません。');sessionStorage.setItem('np1.apnJob',JSON.stringify({id:value.id,revision}))}
 while(active&&(value.status==='queued'||value.status==='running')){
  if(Date.now()>deadline)throw new Error('適用処理の完了をまだ確認できません。再読み込みすると確認を続けます。')
  message.value=value.status==='queued'?'適用を準備しています…':'APN設定と接続状態を確認しています…'
  await new Promise(resolve=>setTimeout(resolve,1000));if(!active)return
  const controller=new AbortController();jobRequest=controller;const timeout=setTimeout(()=>controller.abort(),8000)
  try{value=await api<APNJob>(`/network/cellular/apn/jobs/${value.id}`,'GET',undefined,true,controller.signal)}finally{clearTimeout(timeout);jobRequest=undefined}
 }
 if(!active)return
 if(value.status==='failed'){sessionStorage.removeItem('np1.apnJob');throw new Error(applyFailure(value))}
 if(value.verified!==true||value.appliedRevision!==revision)throw new Error('回線への反映を確認できません。現在の状態を読み直してください。')
 sessionStorage.removeItem('np1.apnJob');message.value=value.result?.dataLink?.status==='available'&&value.result.dataLink.linuxEgressConfigured===true?'APN設定を本体へ反映しました。4Gの通信経路が設定されています。':'APN設定を本体へ反映しました。4Gの通信経路は未接続です。';emit('refresh')
}
async function applyAPN(){if(applyDisabled.value||!apn.value)return;applying.value=true;error.value='';message.value='';const revision=apn.value.revision;try{const value=await api<APNJob>('/network/cellular/apn/apply','POST',{expectedRevision:revision});await trackJob(value,revision)}catch(e){if(active){message.value='';error.value=explain(e)}}finally{if(active){applying.value=false;await loadAPN(true)}}}
async function resumeJob(){try{const stored=sessionStorage.getItem('np1.apnJob');if(!stored)return;const job=JSON.parse(stored);if(!/^[a-f0-9]{48}$/.test(job.id)||!Number.isInteger(job.revision)){sessionStorage.removeItem('np1.apnJob');return}applying.value=true;await trackJob({id:job.id,status:'running',verified:false},job.revision)}catch(e){if(active)error.value=explain(e)}finally{if(active){applying.value=false;await loadAPN(true)}}}
const {cellular,sampledAt,stale:trafficStale}=useTraffic(()=>props.summary)
const month=computed(()=>networkTotal(cellular.value,'month'))
const limit=computed(()=>trafficInteger(plan.value?.cellularLimitBytes)),remaining=computed(()=>limit.value!==null&&limit.value>0n&&month.value!==null?limit.value>month.value?limit.value-month.value:0n:null)
const usedPercent=computed(()=>limit.value&&month.value!==null?Math.min(100,Number(month.value*10000n/limit.value)/100):null)
function toGB(value:bigint){return `${value/1000000000n}${value%1000000000n?'.'+(value%1000000000n).toString().padStart(9,'0').replace(/0+$/,''):''}`}
async function loadPlan(){try{const value=await api<Settings>('/settings');if(active){plan.value=value;const number=trafficInteger(value.cellularLimitBytes);limitDraft.value=number&&number>0n?toGB(number):''}}catch(e){if(active)planError.value=explain(e)}}
async function savePlan(){if(!plan.value||planBusy.value)return;const value=limitDraft.value.trim();if(!/^(?:0|[1-9]\d{0,5})(?:\.\d{1,3})?$/.test(value)){planError.value='月間上限を0〜100,000 GBで入力してください。';return}const [whole,fraction='']=value.split('.'),bytes=BigInt(whole)*1000000000n+BigInt(fraction.padEnd(9,'0'));if(bytes>100000000000000n){planError.value='月間上限は100,000 GB以下にしてください。';return}planBusy.value=true;planError.value='';planMessage.value='';try{const value=await api<Settings>('/settings','PUT',{expectedRevision:plan.value.revision,settings:{...plan.value,cellularLimitBytes:bytes.toString()}});if(active){plan.value=value;planMessage.value='月間上限を保存しました。'}}catch(e){if(active){planError.value=explain(e);if(e instanceof Error&&e.message.includes('409:'))await loadPlan()}}finally{if(active)planBusy.value=false}}
onMounted(()=>{loadAPN();loadPlan();resumeJob()});onUnmounted(()=>{active=false;jobRequest?.abort();for(const profile of drafts.value){profile.username='';profile.password=''}})
</script>

<template>
 <div class="cellular-page">
  <section class="panel cellular-connection"><div class="cellular-connection-main"><span class="cellular-eyebrow"><Radio :size="17"/>MOBILE NETWORK</span><div class="cellular-network-name"><h1>{{carrier}}</h1><span class="cellular-registration" :class="{online:modem?.registered===true&&!stale,stale}">{{registered}}</span></div><div class="cellular-session"><span>{{modem?.rat||'無線方式未取得'}}<b>{{band}}</b></span><span>通信接続<b>{{state(modem?.pdpConnected)}}</b></span><span>WAN IPv4<b class="mono">{{current?.wanIPv4||modem?.wanIPv4||'未取得'}}</b></span></div><p data-testid="cellular-apn-identity">{{apnName.label}} <strong>{{apnName.value}}</strong><span v-if="apnName.saved" class="cellular-apn-source" data-testid="configured-apn-source">{{apnName.description}}</span></p></div><div class="cellular-signal"><div class="cellular-signal-heading"><Signal :size="17"/><strong>電波の状態</strong><button class="icon-button" aria-label="回線状態を更新" @click="emit('refresh')"><RefreshCw :size="16"/></button></div><dl><div><dt>RSRP</dt><dd>{{metric(modem?.rsrp,'dBm')}}</dd></div><div><dt>RSRQ</dt><dd>{{metric(modem?.rsrq,'dB')}}</dd></div><div><dt>SNR</dt><dd>{{metric(modem?.snr,'dB')}}</dd></div></dl><p>{{stale?'更新が止まっています':'最終観測 '+date(observation?.observedAt)}}<span v-if="modem?.plmn"> · PLMN {{modem.plmn}}</span></p></div></section>

  <section class="panel cellular-apn" aria-labelledby="apn-heading"><header class="cellular-section-head"><div><h2 id="apn-heading"><SlidersHorizontal :size="20"/>APN接続設定</h2><p>2つの接続プロファイルを保存し、確認してから回線に適用します。</p></div><button class="secondary compact" :disabled="saving||applying||loading" @click="loadAPN()"><RefreshCw :size="14"/>読み直す</button></header>
   <div v-if="error" class="cellular-message error" role="alert">{{error}}</div><div v-if="message" class="cellular-message" role="status"><Check :size="15"/>{{message}}</div>
   <div v-if="loading&&!apn" class="cellular-loading">保存した接続設定を読み込んでいます…</div>
   <template v-if="apn&&editor"><div class="cellular-apn-layout"><div class="cellular-apn-editor"><div class="cellular-profile-tabs" role="tablist" aria-label="APNプロファイル"><button v-for="profile in drafts" :key="profile.id" role="tab" :aria-selected="selected===profile.id" :class="{selected:selected===profile.id}" :disabled="saving||applying||loading" @click="selected=profile.id">プロファイル {{profile.id==='profile1'?'1':'2'}}<span>{{profile.enabled?'設定対象':'未使用'}}</span></button></div><div class="cellular-profile-fields" role="tabpanel"><label class="cellular-enable"><input v-model="editor.enabled" type="checkbox" :disabled="saving||applying||loading">このプロファイルを接続に使用する</label><label>APN<input v-model="editor.apn" autocomplete="off" spellcheck="false" placeholder="例: provider.example" maxlength="49" :disabled="saving||applying||loading" :aria-label="selected+'のAPN'"></label><label>認証方式<select v-model.number="editor.auth" :disabled="saving||applying||loading" aria-label="APN認証方式"><option :value="0">認証なし（None）</option><option :value="1">PAP</option><option :value="2">CHAP</option><option :value="3">PAP または CHAP</option></select></label><div class="cellular-credentials"><label>ユーザー名 <span>{{editor.usernameConfigured?'保存済み':'未設定'}}</span><input v-model="editor.username" type="password" autocomplete="new-password" spellcheck="false" maxlength="49" :placeholder="editor.usernameConfigured?'変更する場合のみ入力':'プロバイダー指定のユーザー名'" :disabled="saving||applying||loading||editor.clearUsername" aria-label="APNユーザー名"><small><input v-model="editor.clearUsername" type="checkbox" :disabled="saving||applying||loading||!editor.usernameConfigured">保存済みユーザー名を消去</small></label><label>パスワード <span>{{editor.passwordConfigured?'保存済み':'未設定'}}</span><input v-model="editor.password" type="password" autocomplete="new-password" maxlength="49" :placeholder="editor.passwordConfigured?'変更する場合のみ入力':'プロバイダー指定のパスワード'" :disabled="saving||applying||loading||editor.clearPassword" aria-label="APNパスワード"><small><input v-model="editor.clearPassword" type="checkbox" :disabled="saving||applying||loading||!editor.passwordConfigured">保存済みパスワードを消去</small></label></div><p class="cellular-field-note"><LockKeyhole :size="14"/>保存済みのユーザー名・パスワードは表示しません。空欄のまま保存すると現在の値を保ちます。</p></div></div>
    <aside class="cellular-apn-review"><h3>保存している接続設定</h3><dl v-for="profile in apn.profiles" :key="profile.id"><dt>プロファイル {{profile.id==='profile1'?'1':'2'}}<span>{{profile.enabled?'設定対象':'未使用'}}</span></dt><dd>{{profile.apn||'APN未設定'}}</dd></dl><p>保存日時 <b>{{date(apn.savedAt)}}</b></p><p>回線への反映 <b>{{apn.appliedRevision===null?'未適用':apn.appliedRevision===apn.revision?'保存設定を反映済み':'前の保存設定を反映済み'}}</b></p><div v-if="dirty" class="cellular-draft-notice">編集した内容は、まだ保存されていません。</div><div v-else-if="apn.appliedRevision!==apn.revision" class="cellular-draft-notice">この保存設定は、まだ回線へ適用していません。</div></aside></div>
    <footer class="cellular-apn-actions"><div><button class="primary" :disabled="!dirty||saving||applying||loading" @click="saveAPN"><Save :size="16"/>{{saving?'保存中…':'接続設定を保存'}}</button><button class="secondary" :disabled="applyDisabled" @click="applyAPN">{{applying?'回線への反映を確認中…':'保存した設定を適用'}}</button></div><p>{{dirty?'先に編集内容を保存してください。':!enabledCount?'接続に使用するプロファイルを有効にしてください。':!apn.applyAvailable?(apn.applyReason||'回線へ適用する機能の準備状況を確認しています。'):applying?'接続が切り替わります。Wi-Fi/APまたはUSBの管理接続を維持してください。':'適用すると、現在の4G接続を切り替えます。保存だけでは回線を変更しません。'}}</p></footer>
   </template><p v-else-if="!loading" class="cellular-loading">接続設定を読み直してから編集してください。</p>
  </section>

  <details class="panel cellular-usage"><summary><span><Database :size="19"/><strong>通信量・月間上限</strong></span><span>今月 {{trafficVolume(month)}}<ChevronDown :size="17"/></span></summary><div class="cellular-usage-body"><div class="cellular-usage-table"><div><span>期間</span><span><ArrowDown :size="13"/>受信</span><span><ArrowUp :size="13"/>送信</span></div><div><strong>本日の記録分</strong><span>{{trafficVolume(trafficInteger(cellular?.todayRX))}}</span><span>{{trafficVolume(trafficInteger(cellular?.todayTX))}}</span></div><div><strong>今月の記録分</strong><span>{{trafficVolume(trafficInteger(cellular?.monthRX))}}</span><span>{{trafficVolume(trafficInteger(cellular?.monthTX))}}</span></div><div><strong>現在の速度</strong><span>{{trafficSpeed(cellular,'rxBytesPerSecond',trafficStale)}}</span><span>{{trafficSpeed(cellular,'txBytesPerSecond',trafficStale)}}</span></div></div><div class="cellular-quota"><div><span>記録からの残り目安</span><strong>{{remaining===null?'—':trafficVolume(remaining)}}<small>/ {{limit&&limit>0n?trafficVolume(limit):'上限未設定'}}</small></strong><progress v-if="usedPercent!==null" max="100" :value="usedPercent" aria-label="月間上限に対する記録分"></progress></div><form @submit.prevent="savePlan"><label>月間上限（GB）<input v-model="limitDraft" inputmode="decimal" placeholder="20" :disabled="!plan||planBusy" aria-label="4Gの月間上限"></label><button type="submit" class="secondary compact" :disabled="!plan||planBusy">{{planBusy?'保存中…':'上限を保存'}}</button></form><p v-if="planError" class="error" role="alert">{{planError}}</p><p v-if="planMessage" role="status">{{planMessage}}</p></div></div><p class="cellular-usage-foot">{{trafficStale?'更新が止まっています。':'最終更新 '+date(sampledAt)+'。'}}受信と送信の記録分を集計します。0 GBで上限を解除できます。</p></details>
 </div>
</template>
